import{_ as o,o as t,c as i,a5 as a}from"./chunks/framework.Cct9zD0Q.js";const r="/RBQ/nightly/images/operation/iptime-home.ko.png",c="/RBQ/nightly/images/operation/iptime-wisp-mode.ko.png",n="/RBQ/nightly/images/operation/iptime-wisp-scan.ko.png",d="/RBQ/nightly/images/operation/iptime-wisp-form.ko.png",l="/RBQ/nightly/images/operation/iptime-dynamic-ip.ko.png",f=JSON.parse('{"title":"로봇을 인터넷에 연결하기","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/operation/robot-internet.md","filePath":"ko/manual/operation/robot-internet.md","lastUpdated":1795599730000}'),s={name:"ko/manual/operation/robot-internet.md"};function p(m,e,g,h,u,x){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="로봇을-인터넷에-연결하기" tabindex="-1">로봇을 인터넷에 연결하기 <a class="header-anchor" href="#로봇을-인터넷에-연결하기" aria-label="Permalink to &quot;로봇을 인터넷에 연결하기&quot;">​</a></h1><p>원격 점검과 원격 앱 연결은 로봇이 직접 인터넷에 닿아야 합니다. 로봇 공유기가 현장 와이파이에 손님으로 붙어(무선 WAN, WISP라고도 합니다) 그 인터넷을 로봇과 나눠 씁니다. 로봇에 USIM이 들어 있으면 이미 인터넷에 붙어 있으니 이 페이지는 건너뛰세요.</p><h2 id="before" tabindex="-1">시작하기 전에 <a class="header-anchor" href="#before" aria-label="Permalink to &quot;시작하기 전에 {#before}&quot;">​</a></h2><ul><li>인터넷이 되는 현장 와이파이의 이름과 비밀번호</li><li>로봇 와이파이(<code>RBQ_{XX}</code>)에 붙은 휴대폰·태블릿·PC</li><li>공유기 관리자 비밀번호. 모르면 지원 담당에게 문의하세요.</li></ul><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">참고</p><p>웹 로그인 화면이 뜨거나 기기(MAC) 등록이 필요한 망에서는 안 됩니다. 이럴 때는 휴대폰 핫스팟을 켜고, 같은 방법으로 핫스팟을 현장 와이파이로 골라 붙이세요.</p></div></div><h2 id="open" tabindex="-1">1단계: 공유기 설정 열기 <a class="header-anchor" href="#open" aria-label="Permalink to &quot;1단계: 공유기 설정 열기 {#open}&quot;">​</a></h2><ol><li>로봇 와이파이에 붙은 기기의 브라우저에서 <code>http://192.168.0.1</code>을 엽니다.</li><li><code>로그인 이름</code>과 <code>로그인 암호</code>를 넣고 <code>로그인</code>을 누릅니다.</li><li>다음 화면에서 <code>관리도구</code>를 누릅니다. <code>설정마법사</code>는 고르지 마세요.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+r+'" alt="ipTIME 로그인 뒤 첫 화면" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ 관리도구 고르기 ]</figcaption></figure><h2 id="wisp" tabindex="-1">2단계: 무선 WAN 켜기 <a class="header-anchor" href="#wisp" aria-label="Permalink to &quot;2단계: 무선 WAN 켜기 {#wisp}&quot;">​</a></h2><ol><li>왼쪽 <code>전체 메뉴</code>에서 <code>무선랜 관리</code> › <code>무선 확장 설정</code>으로 갑니다.</li><li><strong>2.4GHz</strong> 칸의 목록에서 <code>무선 WAN</code>을 고릅니다. <code>브리지</code>는 고르지 마세요 — 로봇 주소가 바뀝니다.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+c+'" alt="무선 확장 설정의 2.4GHz 동작 방식 목록" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ 2.4GHz 에서 무선 WAN 고르기 ]</figcaption></figure><ol start="3"><li><em>무선 WAN을 사용하면 유선 WAN을 사용할 수 없습니다.</em> 안내와 함께 입력 칸이 나옵니다. <code>네트워크 이름</code> 옆 검색 버튼(<code>확장하여 연결할 WiFi 검색</code>)을 누릅니다.</li><li><code>연결할 WiFi</code> 창에서 현장 와이파이를 고릅니다. 이름 옆에 채널과 감도가 보입니다. 찾는 와이파이가 없으면 창 위쪽 새로 고침 버튼을 누릅니다.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+n+'" alt="연결할 WiFi 검색 창" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ 연결할 WiFi 고르기 (와이파이 이름은 가렸습니다) ]</figcaption></figure><ol start="5"><li><code>네트워크 이름</code>과 <code>인증 및 암호화</code>가 채워지고 <code>암호</code> 칸이 생깁니다. 현장 와이파이 비밀번호를 넣고 2.4GHz 칸의 <code>적용</code>을 누릅니다.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+d+'" alt="무선 WAN 입력 칸" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ 암호를 넣고 적용 ]</figcaption></figure><ol start="6"><li>붙으면 2.4GHz 칸에 <code>무선 WAN 연결됨</code>과 신호 세기가 표시됩니다.</li></ol><p><strong>5GHz</strong>는 <code>중단</code>으로 둡니다. 로봇 자체 와이파이가 5GHz면, 여기서 무선 WAN을 켤 때 바꾸는 동안 컨트롤러 연결이 끊길 수 있습니다.</p><h2 id="dynamic-ip" tabindex="-1">3단계: 동적 IP 쓰기 <a class="header-anchor" href="#dynamic-ip" aria-label="Permalink to &quot;3단계: 동적 IP 쓰기 {#dynamic-ip}&quot;">​</a></h2><p><code>네트워크 관리</code> › <code>인터넷 설정 정보</code>로 갑니다(왼쪽 위 바로 가기에도 있습니다). <code>고정 IP 방식</code>이 골라져 있으면 이전 현장의 주소가 남아 있는 것이라 인터넷이 안 됩니다. <code>동적 IP 방식</code>을 고르고 <code>적용</code>을 누릅니다.</p><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+l+'" alt="인터넷 설정 정보 화면" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ 동적 IP 방식 고르기 ]</figcaption></figure><h2 id="dns" tabindex="-1">4단계: 로봇 DNS 설정 <a class="header-anchor" href="#dns" aria-label="Permalink to &quot;4단계: 로봇 DNS 설정 {#dns}&quot;">​</a></h2><p>로봇 PC는 고정 주소를 쓰기 때문에 공유기에서 이름 풀이(DNS) 서버를 받지 않습니다. DNS가 비어 있는 로봇은 공유기가 인터넷에 붙어도 원격 점검 서버를 찾지 못합니다.</p><ol><li>앱에서 제어권을 가져옵니다.</li><li><strong>정비</strong> › <code>로봇 점검</code>을 열고 맨 아래 <code>원격 점검</code>으로 내려갑니다.</li><li><code>DNS 설정</code>을 누릅니다. <em>DNS 를 설정했습니다</em> 가 나오면 됩니다.</li></ol><p>로봇이 DNS를 로봇 공유기(<code>192.168.0.1</code>)로 맞춥니다. 한 번 설정하면 현장이 바뀌어도 다시 할 필요가 없습니다 — 공유기가 무선 WAN으로 붙은 망의 DNS로 넘겨 줍니다.</p><h2 id="check" tabindex="-1">5단계: 확인 <a class="header-anchor" href="#check" aria-label="Permalink to &quot;5단계: 확인 {#check}&quot;">​</a></h2><p>앱 <strong>정비</strong> › <code>로봇 점검</code>을 열고 맨 아래 <code>원격 점검</code>으로 내려갑니다. 로봇이 인터넷에 닿으면 인터넷 경고가 사라지고 켜기 버튼이 눌립니다. 경고가 그대로면 위 단계를 다시 확인하거나 지원 담당에게 문의하세요.</p>',26)])])}const _=o(s,[["render",p]]);export{f as __pageData,_ as default};
